  if (typeof component === 'object') {
    component.tag = originalTag
  }

  const props = propsToData(node, documentMeta)
  if (keyInParent) {
    props.key = keyInParent
  }

  return h(
    component as any,
    props,
    _renderSlots(
      node,
      h,
      {
        documentMeta,
        parentScope: { ...parentScope, ...props },
        resolveComponent: _resolveComponent
      })
